<script setup>
import { computed, onBeforeUnmount, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { analyzeIndustrialIssue } from '@/industrialAI'

const issue = ref('精轧阶段轧制力异常升高')
const loading = ref(false)
const result = ref(null)
const confirmed = ref(false)
const industrialData = ref({ productionStatus: '精轧工序运行中', rollingForce: 31280, rollingSpeed: 2.86, vibration: 4.6, slabTemperature: 1098, thicknessDeviation: 0.12, qualifiedRate: 98.7 })
const analysisSteps = ['调用工业知识本体', '匹配历史案例', '分析设备状态', '生成决策方案']
const currentStep = ref(-1)
let stepTimer
const history = ref([{ id:'DEC-001', issue:'精轧机振动趋势升高', risk:'高', time:'10:36', status:'已执行' },{ id:'DEC-002', issue:'板坯出炉温度偏低', risk:'中', time:'09:18', status:'已确认' },{ id:'DEC-003', issue:'成品板厚偏差增大', risk:'中', time:'08:42', status:'已执行' }])
const examples = ['精轧阶段轧制力异常升高','加热炉二区温度持续偏高','精轧机轴承振动值升高','产品板厚偏差连续增大']
const riskClass = computed(() => result.value ? `risk-${result.value.risk}` : '')
async function analyze(){ if(!issue.value.trim()) return ElMessage.warning('请输入生产异常情况'); loading.value=true; confirmed.value=false; result.value=null; currentStep.value=0; clearInterval(stepTimer); stepTimer=setInterval(()=>{if(currentStep.value<analysisSteps.length-1)currentStep.value++},320); try{ result.value=await analyzeIndustrialIssue(issue.value,{equipment:'FM-01 精轧机',process:'精轧'}); history.value.unshift({id:result.value.id.slice(-10),issue:issue.value,risk:result.value.risk,time:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),status:'待确认'}) } finally { clearInterval(stepTimer); currentStep.value=analysisSteps.length; loading.value=false } }
function confirmDecision(){ confirmed.value=true; const item=history.value.find(i=>i.issue===result.value.issue); if(item)item.status='已确认'; ElMessage.success('决策方案已确认，已下发生产执行队列') }
onBeforeUnmount(()=>clearInterval(stepTimer))
</script>
<template>
 <div class="decision-page">
  <section class="page-header"><div><p>INDUSTRIAL FOUNDATION MODEL DECISION</p><h2>工业大模型辅助决策</h2></div><div class="model"><i></i><b>工业基座大模型 · 模拟推理</b><el-tag type="primary" size="small">模拟</el-tag></div></section>
  <section class="workspace">
   <article class="input-panel"><header><i></i><h3>工业数据输入</h3><span>INDUSTRIAL DATA INPUT</span></header><div class="data-groups"><section><h4><el-icon><TrendCharts/></el-icon>生产状态</h4><div><span>当前工序</span><b>{{industrialData.productionStatus}}</b></div><div><span>板坯温度</span><b>{{industrialData.slabTemperature}} ℃</b></div></section><section><h4><el-icon><Setting/></el-icon>设备参数</h4><div><span>轧制力</span><b>{{industrialData.rollingForce}} kN</b></div><div><span>轧制速度</span><b>{{industrialData.rollingSpeed}} m/s</b></div><div><span>轴承振动</span><b class="warn">{{industrialData.vibration}} mm/s</b></div></section><section><h4><el-icon><CircleCheck/></el-icon>质量数据</h4><div><span>厚度偏差</span><b>{{industrialData.thicknessDeviation}} mm</b></div><div><span>产品合格率</span><b>{{industrialData.qualifiedRate}}%</b></div></section></div><h4 class="issue-title">异常情况描述</h4><el-input v-model="issue" type="textarea" :rows="3" maxlength="300" show-word-limit/><div class="examples"><button v-for="item in examples" :key="item" @click="issue=item">{{item}}</button></div><el-button type="primary" size="large" :loading="loading" class="analyze-btn" @click="analyze"><el-icon><MagicStick/></el-icon>启动工业基座大模型分析</el-button></article>
   <article class="result-panel" :class="riskClass"><header><div><i></i><h3>结构化诊断报告</h3><span>DIAGNOSTIC REPORT</span></div><em v-if="result">MODEL CONFIDENCE {{result.confidence}}%</em></header><div v-if="loading" class="reasoning"><h3>工业基座大模型分析过程</h3><div v-for="(step,index) in analysisSteps" :key="step" :class="{active:index===currentStep,done:index<currentStep}"><span><el-icon><Check v-if="index<currentStep"/><Loading v-else-if="index===currentStep"/><MoreFilled v-else/></el-icon></span><p><b>{{step}}</b><small>{{['检索厚板生产六层本体与语义关系','检索 1,286 条历史生产异常案例','融合模拟温度、压力、振动与质量指标','输出风险评级与可执行优化参数'][index]}}</small></p></div></div><div v-else-if="!result" class="placeholder"><el-icon><Opportunity/></el-icon><b>等待工业数据输入</b><span>诊断报告将在分析完成后生成</span></div><div v-else class="result"><div class="report-summary"><div><span>异常类型</span><b>{{result.abnormalType}}</b></div><div><span>风险等级</span><b class="danger">{{result.risk}}风险</b></div><div><span>置信度</span><b class="confidence">{{result.confidence}}%</b></div></div><div class="result-top"><div><small>诊断对象</small><h3>{{result.issue}}</h3><p>{{result.context.batch}} · {{result.context.equipment}} · {{result.timestamp}}</p></div></div><section><h4><span>01</span>分析依据</h4><ol><li v-for="item in result.knowledgeBasis" :key="item">{{item}}</li></ol></section><section><h4><span>02</span>建议措施</h4><ul><li v-for="item in result.suggestions" :key="item"><el-icon><CircleCheck/></el-icon>{{item}}</li></ul></section><div class="decision-actions"><el-alert v-if="confirmed" title="方案已确认并下发执行" type="success" :closable="false" show-icon/><template v-else><el-button type="success" size="large" @click="confirmDecision">决策确认并下发</el-button><el-button size="large" @click="ElMessage.info('已转交值班工艺工程师')">转人工复核</el-button></template></div></div></article>
  </section>
  <section class="history"><header><i></i><h3>近期决策记录</h3><span>DECISION HISTORY</span></header><div v-for="item in history.slice(0,4)" :key="item.id" class="history-row"><span>{{item.id}}</span><b>{{item.issue}}</b><el-tag :type="item.risk==='高'?'danger':'warning'" size="small">{{item.risk}}风险</el-tag><span>{{item.time}}</span><em>{{item.status}}</em></div></section>
 </div>
</template>
