.data-groups{display:grid;gap:7px;margin:12px 0}.data-groups section{padding:9px 10px;background:#08243a;border:1px solid #194663}.data-groups h4{display:flex;align-items:center;gap:6px;margin:0 0 7px;color:#4db8e3;font-size:10px}.data-groups section>div{display:flex;justify-content:space-between;margin-top:5px;color:#698ba1;font-size:9px}.data-groups section b{color:#b9d2df;font:10px Consolas}.data-groups .warn{color:#ffae48}.issue-title{margin:10px 0 7px;color:#7898ad;font-size:10px}.reasoning{padding:28px 35px}.reasoning>h3{margin:0 0 24px;color:#d8ebf5;font-size:16px}.reasoning>div{position:relative;display:flex;gap:13px;min-height:75px;opacity:.45}.reasoning>div:not(:last-child)::after{content:'';position:absolute;left:15px;top:32px;width:1px;height:42px;background:#28536d}.reasoning>div.active,.reasoning>div.done{opacity:1}.reasoning>div>span{width:31px;height:31px;display:grid;place-items:center;flex:0 0 31px;color:#698da3;background:#0c3551;border:1px solid #275a78;border-radius:50%}.reasoning>div.active>span{color:#45c8f0;border-color:#45c8f0;box-shadow:0 0 12px rgba(69,200,240,.3)}.reasoning>div.done>span{color:#2bd398;border-color:#2bd398}.reasoning p{display:flex;flex-direction:column;margin:1px 0}.reasoning b{color:#c6dce8;font-size:12px}.reasoning small{margin-top:6px;color:#64879d;font-size:9px}.report-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:15px}.report-summary>div{display:flex;flex-direction:column;padding:11px;background:#092942;border:1px solid #1f4b68}.report-summary span{color:#6789a0;font-size:9px}.report-summary b{margin-top:5px;color:#d5e8f2;font-size:13px}.report-summary .danger{color:#ef6565}.report-summary .confidence{color:#2bd398;font-family:Consolas}
